#!/usr/bin/env node
/**
 * Applies FoxiesDeck's reproducible Android shell configuration to the
 * project generated by Bubblewrap. Bubblewrap still supplies the signing
 * identity, icons and version metadata; this patch replaces the TWA runtime
 * with a WebView shell that can serve the web app's media from an install-time
 * Play Asset Pack.
 */
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { validateGoogleServicesConfig } from "./google-services-config.mjs";

export { validateGoogleServicesConfig } from "./google-services-config.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const TEMPLATE_DIR = path.join(__dirname, "android-template");

export const ANDROID_TARGET_SDK = 36;
export const PLAY_BILLING_VERSION = "8.0.0";
export const PLAY_APP_UPDATE_VERSION = "2.1.0";
export const ASSET_DELIVERY_VERSION = "2.3.0";
export const PLAY_REVIEW_VERSION = "2.0.2";
export const ANDROID_JAVA_TEMPLATE_FILES = [
  "Application.java",
  "LauncherActivity.java",
  "LocalMediaWebViewClient.java",
  "NativeMediaStore.java",
  "NativeBillingBridge.java",
  "NativeTextToSpeechBridge.java",
  "NativeVibrationBridge.java",
  "EventReceiverActivity.java",
];

const FILE_PROVIDER_PATHS = `<?xml version="1.0" encoding="utf-8"?>
<paths xmlns:android="http://schemas.android.com/apk/res/android">
    <cache-path name="camera" path="camera/" />
</paths>
`;

async function readText(filePath) {
  return fs.readFile(filePath, "utf8");
}

async function writeText(filePath, contents) {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, contents, "utf8");
}

export async function verifyGoogleServicesConfig(projectDir, expectedPackageName) {
  const configPath = path.join(projectDir, "app", "google-services.json");
  let contents;
  try {
    contents = await readText(configPath);
  } catch {
    throw new Error(
      `Firebase config is missing: ${configPath}. Restore the matching google-services.json before building the Android app.`,
    );
  }

  return validateGoogleServicesConfig(contents, expectedPackageName);
}

function matchValue(contents, expression, fallback) {
  return contents.match(expression)?.[1] || fallback;
}

function quoteGroovy(value) {
  return String(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function buildAppGradle({ packageName, host, versionCode, versionName, minSdkVersion }) {
  return `plugins {
    id 'com.android.application'
    id 'com.google.gms.google-services'
}

android {
    namespace "${quoteGroovy(packageName)}"
    compileSdk ${ANDROID_TARGET_SDK}

    defaultConfig {
        applicationId "${quoteGroovy(packageName)}"
        minSdk ${minSdkVersion}
        targetSdk ${ANDROID_TARGET_SDK}
        versionCode ${versionCode}
        versionName "${quoteGroovy(versionName)}"

        resValue "string", "appName", "FoxiesDeck"
        resValue "string", "launcherName", "FoxiesDeck"
        resValue "string", "launchUrl", "https://${quoteGroovy(host)}/"
        resValue "string", "hostName", "${quoteGroovy(host)}"
    }

    // The UI media is delivered inside the AAB as an install-time asset pack.
    assetPacks = [":ui-media"]

    buildTypes {
        debug {
            minifyEnabled false
        }
        release {
            minifyEnabled true
            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'
        }
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_1_8
        targetCompatibility JavaVersion.VERSION_1_8
    }

    sourceSets {
        main {
            java {
                // Bubblewrap's old TWA implementation remains on disk as a
                // rollback reference, but is not part of the hybrid release.
                exclude 'com/foxiesdeck/**'
                exclude 'com/LigidTools/Glidecore/DelegationService.java'
            }
        }
    }

    lint {
        checkReleaseBuilds false
    }
}

dependencies {
    implementation fileTree(include: ['*.jar'], dir: 'libs')

    // Native Play Billing is exposed to the remote web app through the
    // FoxiesDeckNativeBilling JavaScript bridge.
    implementation 'com.android.billingclient:billing:${PLAY_BILLING_VERSION}'

    // Google Play Immediate In-App Updates gate the first WebView load when a
    // newer Play-distributed version is available.
    implementation 'com.google.android.play:app-update:${PLAY_APP_UPDATE_VERSION}'

    // FileProvider exposes camera captures to the WebView without broad
    // external-storage permissions.
    implementation 'androidx.core:core:1.16.0'

    // Install-time media delivery for the App Bundle.
    implementation 'com.google.android.play:asset-delivery:${ASSET_DELIVERY_VERSION}'
    implementation 'com.google.android.play:review:${PLAY_REVIEW_VERSION}'

    implementation platform('com.google.firebase:firebase-bom:33.1.2')
    implementation 'com.google.firebase:firebase-analytics'
    implementation 'androidx.lifecycle:lifecycle-process:2.8.7'
}
`;
}

const HYBRID_MANIFEST = ({ packageName }) => `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools">
    <uses-permission android:name="android.permission.INTERNET" />
    <uses-permission android:name="android.permission.RECORD_AUDIO" />
    <uses-permission android:name="android.permission.VIBRATE" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
    <uses-permission android:name="com.android.vending.BILLING" />
    <uses-permission android:name="com.google.android.gms.permission.AD_ID" tools:node="remove" />
    <uses-permission android:name="android.permission.ACCESS_ADSERVICES_AD_ID" tools:node="remove" />

    <!-- Android 11+ hides TTS engines unless the app declares this query. -->
    <queries>
        <intent>
            <action android:name="android.intent.action.TTS_SERVICE" />
        </intent>
    </queries>

    <application
        android:name="${packageName}.Application"
        android:allowBackup="true"
        android:hardwareAccelerated="true"
        android:icon="@mipmap/ic_launcher"
        android:label="@string/appName"
        android:supportsRtl="true"
        android:theme="@style/AppTheme"
        android:usesCleartextTraffic="false">

        <meta-data
            android:name="google_analytics_adid_collection_enabled"
            android:value="false" />

        <activity
            android:name="${packageName}.LauncherActivity"
            android:configChanges="fontScale|fontWeightAdjustment|keyboardHidden|keyboard|orientation|screenLayout|screenSize|smallestScreenSize|uiMode"
            android:exported="true"
            android:launchMode="singleTask"
            android:screenOrientation="portrait">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
            <intent-filter android:autoVerify="true">
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="https" android:host="@string/hostName" />
            </intent-filter>
        </activity>

        <activity
            android:name="${packageName}.EventReceiverActivity"
            android:excludeFromRecents="true"
            android:exported="true"
            android:launchMode="singleTop"
            android:noHistory="true"
            android:theme="@android:style/Theme.Translucent.NoTitleBar">
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="foxiesdeck" android:host="event" />
            </intent-filter>
        </activity>

        <provider
            android:name="androidx.core.content.FileProvider"
            android:authorities="${packageName}.fileprovider"
            android:exported="false"
            android:grantUriPermissions="true">
            <meta-data
                android:name="android.support.FILE_PROVIDER_PATHS"
                android:resource="@xml/file_paths" />
        </provider>
    </application>
</manifest>
`;

const APP_THEME = `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <style name="AppTheme" parent="android:style/Theme.Material.Light.NoActionBar">
        <item name="android:fontFamily">sans</item>
        <item name="android:windowActionModeOverlay">true</item>
        <item name="android:windowNoTitle">true</item>
        <item name="android:colorAccent">#fe6708</item>
        <item name="android:windowLightStatusBar">false</item>
        <item name="android:statusBarColor">#000000</item>
        <item name="android:navigationBarColor">#000000</item>
        <item name="android:windowBackground">#000000</item>
    </style>
</resources>
`;

const APP_THEME_V31 = `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <style name="AppTheme" parent="android:style/Theme.Material.Light.NoActionBar">
        <item name="android:fontFamily">sans</item>
        <item name="android:windowActionModeOverlay">true</item>
        <item name="android:windowNoTitle">true</item>
        <item name="android:colorAccent">#fe6708</item>
        <item name="android:windowLightStatusBar">false</item>
        <item name="android:statusBarColor">#000000</item>
        <item name="android:navigationBarColor">#000000</item>
        <item name="android:windowBackground">#000000</item>
        <item name="android:windowSplashScreenBackground">#000000</item>
        <!-- Keep the Android 12 launch window blank until the WebView paints
             the orange app surface. The social/video splash bitmap is not a
             valid native launch icon and must not be shown here. -->
        <item name="android:windowSplashScreenAnimatedIcon">@drawable/transparent_splash</item>
        <item name="android:windowSplashScreenIconBackgroundColor">#000000</item>
    </style>
</resources>
`;

const TRANSPARENT_SPLASH = `<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="1dp"
    android:height="1dp"
    android:viewportWidth="1"
    android:viewportHeight="1">
    <path
        android:fillColor="@android:color/transparent"
        android:pathData="M0,0h1v1h-1z" />
</vector>
`;

const ASSET_PACK_GRADLE = `plugins {
    id 'com.android.asset-pack'
}

assetPack {
    packName = "ui_media"
    dynamicDelivery {
        deliveryType = "install-time"
    }
}
`;

function buildProguardBridgeRules(packageName, existingRules) {
  const rules = [];
  if (!existingRules.includes("NativeBillingBridge")) {
    rules.push(`-keep class ${packageName}.NativeBillingBridge { *; }`);
  }
  if (!existingRules.includes("NativeVibrationBridge")) {
    rules.push(`-keep class ${packageName}.NativeVibrationBridge { *; }`);
  }
  if (!existingRules.includes("NativeTextToSpeechBridge")) {
    rules.push(`-keep class ${packageName}.NativeTextToSpeechBridge { *; }`);
  }
  if (!existingRules.includes("@android.webkit.JavascriptInterface")) {
    rules.push(`-keepclassmembers class * {
    @android.webkit.JavascriptInterface <methods>;
}`);
  }
  if (rules.length === 0) return "";
  return `
# The remote WebView calls these methods by JavaScript interface name.
${rules.join("\n")}
`;
}

async function patchJavaTemplates(projectDir, packageName) {
  const packagePath = packageName.split(".").join(path.sep);
  const javaDir = path.join(projectDir, "app", "src", "main", "java", packagePath);
  for (const templateName of ANDROID_JAVA_TEMPLATE_FILES) {
    const template = await readText(path.join(TEMPLATE_DIR, templateName));
    await writeText(
      path.join(javaDir, templateName),
      template.replaceAll("__PACKAGE__", packageName),
    );
  }
}

export async function patchGeneratedAndroidProject(
  projectDir = process.env.TWA_PROJECT_DIR || path.join(ROOT, "com.foxiesdeck"),
) {
  const appGradlePath = path.join(projectDir, "app", "build.gradle");
  const existingGradle = await readText(appGradlePath);
  const packageName = matchValue(
    existingGradle,
    /applicationId\s+["']([^"']+)["']/,
    matchValue(existingGradle, /namespace\s+["']([^"']+)["']/, "com.foxiesdeck"),
  );
  const host = matchValue(
    existingGradle,
    /hostName:\s*["']([^"']+)["']/,
    matchValue(existingGradle, /resValue\s+["']string["']\s*,\s*["']hostName["']\s*,\s*["']([^"']+)["']/, "www.foxiesdeck.com"),
  );
  const versionCode = matchValue(existingGradle, /versionCode\s+(\d+)/, "1");
  const versionName = matchValue(existingGradle, /versionName\s+["']([^"']+)["']/, "1.0.0");
  const minSdkVersion = matchValue(existingGradle, /minSdk(?:Version)?\s+(\d+)/, "24");

  // The Google Services plugin can build a Firebase-enabled shell even when
  // the JSON belongs to a different Android package, so check the identity
  // before rewriting or compiling the generated project.
  await verifyGoogleServicesConfig(projectDir, packageName);

  await writeText(
    appGradlePath,
    buildAppGradle({ packageName, host, versionCode, versionName, minSdkVersion }),
  );
  await writeText(path.join(projectDir, "settings.gradle"), "include ':app', ':ui-media'\n");
  await writeText(path.join(projectDir, "ui-media", "build.gradle"), ASSET_PACK_GRADLE);
  await writeText(
    path.join(projectDir, "app", "src", "main", "AndroidManifest.xml"),
    HYBRID_MANIFEST({ packageName }),
  );
  await writeText(path.join(projectDir, "app", "src", "main", "res", "values", "styles.xml"), APP_THEME);
  await writeText(
    path.join(projectDir, "app", "src", "main", "res", "values-v31", "styles.xml"),
    APP_THEME_V31,
  );
  await writeText(
    path.join(projectDir, "app", "src", "main", "res", "drawable-anydpi", "transparent_splash.xml"),
    TRANSPARENT_SPLASH,
  );
  await writeText(
    path.join(projectDir, "app", "src", "main", "res", "xml", "file_paths.xml"),
    FILE_PROVIDER_PATHS,
  );
  await patchJavaTemplates(projectDir, packageName);

  const proguardPath = path.join(projectDir, "app", "proguard-rules.pro");
  let proguard = "";
  try {
    proguard = await readText(proguardPath);
  } catch {
    // The generated project normally has this file, but a clean custom
    // project should still be repairable.
  }
  const missingBridgeRules = buildProguardBridgeRules(packageName, proguard);
  if (missingBridgeRules) {
    await writeText(
      proguardPath,
      `${proguard.trimEnd()}${missingBridgeRules}`,
    );
  }

  const result = {
    projectDir,
    packageName,
    host,
    versionCode: Number.parseInt(versionCode, 10),
    versionName,
    targetSdkVersion: ANDROID_TARGET_SDK,
    playBillingVersion: PLAY_BILLING_VERSION,
    playAppUpdateVersion: PLAY_APP_UPDATE_VERSION,
    assetDeliveryVersion: ASSET_DELIVERY_VERSION,
    runtime: "hybrid-webview",
    assetPack: "ui_media",
  };
  console.log(JSON.stringify(result, null, 2));
  return result;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  patchGeneratedAndroidProject().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}
